--
-- Table structure for table `feedback_questions`
--

DROP TABLE IF EXISTS `feedback_questions`;
CREATE TABLE IF NOT EXISTS `feedback_questions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `question_set_id` int DEFAULT NULL,
  `survey_group_id` int NOT NULL,
  `question_code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_text_en` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_text_mm` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_group_question_code` (`survey_group_id`,`question_code`),
  KEY `idx_fq_question_set_id` (`question_set_id`),
  KEY `idx_fq_group` (`survey_group_id`)
) ENGINE=InnoDB AUTO_INCREMENT=370 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `feedback_questions`
--

INSERT INTO `feedback_questions` (`id`, `question_set_id`, `survey_group_id`, `question_code`, `question_text_en`, `question_text_mm`, `created_at`) VALUES
(1, 1, 1, 'TQ1', 'The lecturer is well prepared for each class.', 'ဆရာ/မသည် အတန်းတစ်ခုချင်းစီအတွက် သင်ကြားရမည့် သင်ခန်းစာများကို စနစ်တကျ ကြိုတင်ပြင်ဆင်၍ သင်ကြားပေးပါသည်။', '2026-08-02 16:31:27'),
(2, 1, 1, 'TQ2', 'The lecturer explains the course content clearly and understandably.', 'ဆရာ/မသည် သင်ခန်းစာအကြောင်းအရာများကို ရှင်းလင်းတိကျပြီး နားလည်လွယ်ကူစွာ ရှင်းပြသင်ကြားပေးပါသည်။', '2026-08-02 16:32:08'),
(3, 1, 1, 'TQ3', 'The lecturer demonstrates good knowledge of the subject.', 'ဆရာ/မသည် သင်ကြားသည့် ဘာသာရပ်နှင့်ပတ်သက်၍ ကျွမ်းကျင်မှုနှင့် လုံလောက်သော ဘာသာရပ်ဆိုင်ရာ အသိပညာကို ပိုင်ဆိုင်ထားပါသည်။', '2026-08-02 16:32:48'),
(4, 1, 1, 'TQ4', 'The lecturer uses effective teaching methods.', 'ဆရာ/မသည် သင်ကြားရာတွင် ကျောင်းသား/သူများ၏ သင်ယူမှုကို အထောက်အကူပြုနိုင်သော ထိရောက်သည့် သင်ကြားရေးနည်းလမ်းများကို အသုံးပြုပါသည်။', '2026-08-02 16:33:38'),
(5, 1, 1, 'TQ5', 'The lecturer encourages students to participate actively in class.', 'ဆရာ/မသည် ကျောင်းသား/သူများအား အတန်းတွင်း ဆွေးနွေးမှုများတွင် တက်ကြွစွာ ပါဝင်ဆောင်ရွက်နိုင်ရန် အားပေးမြှင့်တင်ပေးပါသည်။', '2026-08-02 16:34:22'),
(6, 1, 1, 'TQ6', 'The lecturer responds to students\' questions effectively.', 'ဆရာ/မသည် ကျောင်းသား/သူများ၏ မေးခွန်းများကို ရှင်းလင်းတိကျပြီး နားလည်လွယ်ကူစွာ ဖြေကြားရှင်းလင်းပေးပါသည်။', '2026-08-02 16:35:01'),
(7, 1, 1, 'TQ7', 'The lecturer provides students with sufficient opportunities for meaningful interaction and discussion.', 'ဆရာ/မသည် ကျောင်းသား/သူများနှင့် အပြန်အလှန် ဆက်သွယ်ဆွေးနွေးမှုကို ထိရောက်စွာ ဆောင်ရွက်ပေးပြီး သင်ယူမှုအပေါ် လိုအပ်သော လမ်းညွှန်မှုနှင့် အကြံပြုချက်များကို ပံ့ပိုးပေးပါသည်။', '2026-08-02 16:35:54'),
(8, 1, 1, 'TQ8', 'The lecturer treats students with respect and fairness.', 'ဆရာ/မသည် ကျောင်းသား/သူများအား အပြန်အလှန်လေးစားမှု၊ တရားမျှတမှုနှင့် ပရော်ဖက်ရှင်နယ် ကျင့်ဝတ်တို့ဖြင့် ဆက်ဆံပါသည်။', '2026-08-02 16:36:38'),
(9, 1, 1, 'TQ9', 'The lecturer motivates me to learn and perform well.', 'ဆရာ/မ၏ သင်ကြားပို့ချမှုသည် ကျွန်ုပ်၏ သင်ယူလိုစိတ်နှင့် ပညာရပ်ဆိုင်ရာ စိတ်ဝင်စားမှုကို မြှင့်တင်ပေးပါသည်။', '2026-08-02 16:37:20'),
(22, 2, 4, 'SA1', 'Career guidance and employment services provided by the university are beneficial to my future career development.', 'တက္ကသိုလ်မှ ပံ့ပိုးပေးသော အသက်မွေးဝမ်းကျောင်းလမ်းညွှန်မှုနှင့် အလုပ်အကိုင်အခွင့်အလမ်းဆိုင်ရာ ဝန်ဆောင်မှုများသည် ကျွန်ုပ်၏ အနာဂတ်အသက်မွေးဝမ်းကျောင်း ဖွံ့ဖြိုးတိုးတက်ရေးအတွက် အထောက်အကူပြုပါသည်။', '2026-08-02 16:55:20'),
(23, 2, 4, 'SA2', 'University announcements and important information are communicated to students in a timely manner.', 'တက္ကသိုလ်မှ ထုတ်ပြန်သော ကြေညာချက်များနှင့် အရေးကြီးသော သတင်းအချက်အလက်များကို အချိန်နှင့်တစ်ပြေးညီ သိရှိပါသည်။', '2026-08-02 16:57:05'),
(24, 2, 4, 'SA3', 'Information about scholarships and financial assistance is readily available and sufficient.', 'ပညာသင်ဆု (Scholarship) နှင့် ငွေကြေးအထောက်အပံ့ဆိုင်ရာ အချက်အလက်များကို လုံလောက်စွာ ရရှိပါသည်။', '2026-08-02 16:57:32'),
(25, 2, 4, 'SA4', 'The Student Affairs Office effectively supports and assists students with their needs.', 'ကျောင်းသားရေးရာဌာန (Student Affairs) သည် ကျောင်းသား/သူများ၏ လိုအပ်ချက်များနှင့် အခက်အခဲများကို ထိရောက်စွာ ဖြေရှင်းပေးပြီး လိုအပ်သော ပံ့ပိုးကူညီမှုများကို ပေးအပ်ပါသည်။', '2026-08-02 16:58:37'),
(26, 2, 4, 'SA5', 'Seminars, ICT Project Shows, and training programs organized by the university contribute to my personal and professional development.', 'တက္ကသိုလ်မှ ကျင်းပသော ဟောပြောပွဲများ၊ ICT Project Show များနှင့် သင်တန်းများသည် ကျွန်ုပ်၏ ကိုယ်ရည်ကိုယ်သွေး ဖွံ့ဖြိုးတိုးတက်ရေးနှင့် အသက်မွေးဝမ်းကျောင်းဆိုင်ရာ ကျွမ်းကျင်မှုများ တိုးတက်ရေးအတွက် အထောက်အကူပြုပါသည်။', '2026-08-02 16:59:16'),
(28, 2, 4, 'SA6', 'The university organizes sports competitions (e.g., football, volleyball, badminton, and other sports) in a well-planned manner and encourages student participation.', 'တက္ကသိုလ်သည် ဘောလုံး၊ ဘော်လီဘော၊ ကြက်တောင်နှင့် အခြားအားကစားပြိုင်ပွဲများတွင် ကျောင်းသား/သူများ ပါဝင်နိုင်ရန် စနစ်တကျ စီစဉ်ပံ့ပိုးပေးပါသည်။', '2026-08-02 17:01:04'),
(29, 2, 4, 'SA7', 'The university organizes traditional Myanmar cultural events, such as the Thanaka Application Competition and Htamane Festival, in an engaging and meaningful way.', 'တက္ကသိုလ်သည် သနပ်ခါးလိမ်းပြိုင်ပွဲ၊ ထမနဲထိုးပွဲကဲ့သို့သော မြန်မာ့ရိုးရာယဉ်ကျေးမှုဆိုင်ရာ လှုပ်ရှားမှုများကို စိတ်ဝင်စားဖွယ်ကောင်းစွာ စီစဉ်ကျင်းပပေးပါသည်။', '2026-08-02 17:05:33'),
(30, 2, 4, 'SA8', 'Sports and cultural activities organized by the university promote teamwork, collaboration, and friendship among students.', 'တက္ကသိုလ်မှ စီစဉ်ကျင်းပသော အားကစားပွဲနှင့် ယဉ်ကျေးမှုပွဲများသည် ကျောင်းသား/သူများအကြား အပြန်အလှန်ပူးပေါင်းဆောင်ရွက်မှု၊ ချစ်ကြည်ရင်းနှီးမှုနှင့် အသင်းအဖွဲ့စိတ်ဓာတ်ကို တိုးမြှင့်ပေးပါသည်။', '2026-08-02 17:06:17'),
(32, 3, 7, 'LE1', 'The classrooms provide a comfortable learning environment.', 'စာသင်ခန်းများသည် သက်သောင့်သက်သာရှိပြီး ထိရောက်သော သင်ယူမှုကို အထောက်အကူပြုနိုင်သည့် သင်ယူမှုပတ်ဝန်းကျင် ဖြစ်ပါသည်။', '2026-08-02 17:13:44'),
(33, 3, 7, 'LE2', 'The classrooms are clean, safe, and well maintained.', 'စာသင်ခန်းများသည် သန့်ရှင်းသပ်ရပ်၍ လုံခြုံစိတ်ချရသည့်အပြင် ကောင်းမွန်စွာ ပြုပြင်ထိန်းသိမ်းထားရှိပါသည်။', '2026-08-02 17:14:27'),
(34, 3, 7, 'LE3', 'Classroom facilities (e.g., lighting, seating, ventilation, and audio-visual equipment) are adequate.', 'စာသင်ခန်းများတွင် အလင်းရောင်၊ ထိုင်ခုံ၊ လေဝင်လေထွက်နှင့် သင်ကြားသင်ယူရေးဆိုင်ရာ အထောက်အကူပြုပစ္စည်းများ လုံလောက်စွာ ရှိပါသည်။', '2026-08-02 17:15:07'),
(35, 3, 7, 'LE4', 'Learning resources (e.g., library and learning materials) are sufficient to support my studies.', 'စာကြည့်တိုက်တွင် ကျောင်းသား/သူများ လေ့လာဖတ်ရှုနိုင်ရန် နည်းပညာစာအုပ်များ၊ သုတရသစာအုပ်များ လုံလောက်စွာရှိပါသည်။', '2026-08-02 17:15:40'),
(36, 3, 7, 'LE5', 'The university provides reliable internet and Wi-Fi access for learning.', 'တက္ကသိုလ်မှ ပံ့ပိုးပေးထားသော Internet/Wi-Fi ဝန်ဆောင်မှုသည် သင်ယူလေ့လာရေး၊ သုတေသနလုပ်ငန်းများနှင့် ပညာရေးဆိုင်ရာ လှုပ်ရှားမှုများအတွက် ထိရောက်စွာ အထောက်အကူပြုပါသည်။', '2026-08-02 17:16:02'),
(37, 3, 7, 'LE6', 'The online learning platform(Learning Management System) is easy to access and use.', 'Online Learning Platform (Learning Management System) သည် အသုံးပြုရ လွယ်ကူအဆင်ပြေပြီး သင်ကြားသင်ယူရေးဆိုင်ရာ လုပ်ငန်းစဉ်များကို ထိရောက်စွာ အထောက်အကူပြုပါသည်။', '2026-08-02 17:16:46'),
(38, 3, 7, 'LE7', 'The learning environment encourages active participation and collaboration among students.', 'တက္ကသိုလ်၏ သင်ယူမှုပတ်ဝန်းကျင်သည် ကျောင်းသား/သူများအကြား တက်ကြွစွာ ပါဝင်ဆောင်ရွက်မှု၊ ပူးပေါင်းသင်ယူမှုနှင့် အပြန်အလှန် အသိပညာဖလှယ်မှုတို့ကို အားပေးမြှင့်တင်ပေးပါသည်။', '2026-08-02 17:17:11'),
(39, 3, 7, 'LE8', 'The university provides a supportive and inclusive learning atmosphere.', 'တက္ကသိုလ်သည် ကျောင်းသား/သူအားလုံးအတွက် တန်းတူညီမျှ အခွင့်အရေးရရှိစေပြီး အားပေးကူညီပံ့ပိုးပေးသော၊ အားလုံးပါဝင်နိုင်သည့် သင်ယူမှုပတ်ဝန်းကျင်ကို ဖန်တီးပေးပါသည်။', '2026-08-02 17:17:32'),
(41, 3, 7, 'LE9', 'The campus environment is conducive to learning and academic success.', 'တက္ကသိုလ်၏ ကျောင်းဝင်းပတ်ဝန်းကျင်သည် သင်ယူလေ့လာမှု၊ ပညာရေးဆိုင်ရာ ဖွံ့ဖြိုးတိုးတက်မှုနှင့် ပညာရေးအောင်မြင်မှုတို့ကို အထောက်အကူပြုနိုင်သော အရည်အသွေးမြင့် ပတ်ဝန်းကျင်တစ်ခု ဖြစ်ပါသည်။', '2026-08-02 17:20:24'),
(42, 3, 7, 'LE10', 'Overall, I am satisfied with the university\'s learning environment.', 'ယေဘုယျအားဖြင့် တက္ကသိုလ်၏ သင်ယူမှုပတ်ဝန်းကျင်၊ သင်ကြားသင်ယူရေးဆိုင်ရာ အထောက်အပံ့များနှင့် ပညာရေးဆိုင်ရာ အဆောက်အအုံများ၏ အရည်အသွေးအပေါ် ကျွန်ုပ် ကျေနပ်အားရမှုရှိပါသည်။', '2026-08-02 17:20:54'),
