(290, 30, 37, 'TQ18', 'The course content encourages critical thinking and problem-solving skills.', 'သင်ခန်းစာအကြောင်းအရာများသည် ကျောင်းသား/သူများ၏ ဝေဖန်စဉ်းစားနိုင်စွမ်း၊ ဆန်းစစ်လေ့လာနိုင်စွမ်းနှင့် ပြဿနာဖြေရှင်းနိုင်စွမ်းတို့ကို မြှင့်တင်ပေးပါသည်။', '2026-08-06 06:38:31'),
(291, 30, 37, 'TQ19', 'Overall, I am satisfied with the quality of teaching provided by the lecturer.', 'ယေဘုယျအားဖြင့် ဤဘာသာရပ်နှင့်ပတ်သက်၍ ဆရာ/မ၏ သင်ကြားမှုနည်းစနစ်ကို နှစ်သက်ပါသည်။', '2026-08-06 06:38:31'),
(292, 31, 38, 'SA1', 'Career guidance and employment services provided by the university are beneficial to my future career development.', 'တက္ကသိုလ်မှ ပံ့ပိုးပေးသော အသက်မွေးဝမ်းကျောင်းလမ်းညွှန်မှုနှင့် အလုပ်အကိုင်အခွင့်အလမ်းဆိုင်ရာ ဝန်ဆောင်မှုများသည် ကျွန်ုပ်၏ အနာဂတ်အသက်မွေးဝမ်းကျောင်း ဖွံ့ဖြိုးတိုးတက်ရေးအတွက် အထောက်အကူပြုပါသည်။', '2026-08-06 06:39:36'),
(293, 31, 38, 'SA2', 'University announcements and important information are communicated to students in a timely manner.', 'တက္ကသိုလ်မှ ထုတ်ပြန်သော ကြေညာချက်များနှင့် အရေးကြီးသော သတင်းအချက်အလက်များကို အချိန်နှင့်တစ်ပြေးညီ သိရှိပါသည်။', '2026-08-06 06:39:36'),
(294, 31, 38, 'SA3', 'Information about scholarships and financial assistance is readily available and sufficient.', 'ပညာသင်ဆု (Scholarship) နှင့် ငွေကြေးအထောက်အပံ့ဆိုင်ရာ အချက်အလက်များကို လုံလောက်စွာ ရရှိပါသည်။', '2026-08-06 06:39:36'),
(295, 31, 38, 'SA4', 'The Student Affairs Office effectively supports and assists students with their needs.', 'ကျောင်းသားရေးရာဌာန (Student Affairs) သည် ကျောင်းသား/သူများ၏ လိုအပ်ချက်များနှင့် အခက်အခဲများကို ထိရောက်စွာ ဖြေရှင်းပေးပြီး လိုအပ်သော ပံ့ပိုးကူညီမှုများကို ပေးအပ်ပါသည်။', '2026-08-06 06:39:36'),
(296, 31, 38, 'SA5', 'Seminars, ICT Project Shows, and training programs organized by the university contribute to my personal and professional development.', 'တက္ကသိုလ်မှ ကျင်းပသော ဟောပြောပွဲများ၊ ICT Project Show များနှင့် သင်တန်းများသည် ကျွန်ုပ်၏ ကိုယ်ရည်ကိုယ်သွေး ဖွံ့ဖြိုးတိုးတက်ရေးနှင့် အသက်မွေးဝမ်းကျောင်းဆိုင်ရာ ကျွမ်းကျင်မှုများ တိုးတက်ရေးအတွက် အထောက်အကူပြုပါသည်။', '2026-08-06 06:39:36'),
(297, 31, 38, 'SA6', 'The university organizes sports competitions (e.g., football, volleyball, badminton, and other sports) in a well-planned manner and encourages student participation.', 'တက္ကသိုလ်သည် ဘောလုံး၊ ဘော်လီဘော၊ ကြက်တောင်နှင့် အခြားအားကစားပြိုင်ပွဲများတွင် ကျောင်းသား/သူများ ပါဝင်နိုင်ရန် စနစ်တကျ စီစဉ်ပံ့ပိုးပေးပါသည်။', '2026-08-06 06:39:36'),
(298, 31, 38, 'SA7', 'The university organizes traditional Myanmar cultural events, such as the Thanaka Application Competition and Htamane Festival, in an engaging and meaningful way.', 'တက္ကသိုလ်သည် သနပ်ခါးလိမ်းပြိုင်ပွဲ၊ ထမနဲထိုးပွဲကဲ့သို့သော မြန်မာ့ရိုးရာယဉ်ကျေးမှုဆိုင်ရာ လှုပ်ရှားမှုများကို စိတ်ဝင်စားဖွယ်ကောင်းစွာ စီစဉ်ကျင်းပပေးပါသည်။', '2026-08-06 06:39:36'),
(299, 31, 38, 'SA8', 'Sports and cultural activities organized by the university promote teamwork, collaboration, and friendship among students.', 'တက္ကသိုလ်မှ စီစဉ်ကျင်းပသော အားကစားပွဲနှင့် ယဉ်ကျေးမှုပွဲများသည် ကျောင်းသား/သူများအကြား အပြန်အလှန်ပူးပေါင်းဆောင်ရွက်မှု၊ ချစ်ကြည်ရင်းနှီးမှုနှင့် အသင်းအဖွဲ့စိတ်ဓာတ်ကို တိုးမြှင့်ပေးပါသည်။', '2026-08-06 06:39:36'),
(300, 31, 38, 'SA9', 'The university listens to students\' suggestions and feedback and takes appropriate action when necessary.', 'တက္ကသိုလ်သည် ကျောင်းသား/သူများ၏ အကြံပြုချက်များနှင့် အမြင်များကို အလေးထားနားထောင်ပြီး လိုအပ်သည့်အတိုင်း တာဝန်ယူ၍ ဆောင်ရွက်ပေးပါသည်။', '2026-08-06 06:39:36'),
(301, 31, 38, 'SA10', 'Overall, I am satisfied with the student activities and events organized by the university.', 'ယေဘုယျအားဖြင့် တက္ကသိုလ်မှ စီစဉ်ကျင်းပသော ကျောင်းသားလှုပ်ရှားမှုများ၊ အားကစားနှင့် ယဉ်ကျေးမှုဆိုင်ရာ ပွဲလမ်းသဘင်များအပေါ် ကျွန်ုပ် ကျေနပ်အားရမှုရှိပါသည်။', '2026-08-06 06:39:36'),
(302, 32, 39, 'LE1', 'The classrooms provide a comfortable learning environment.', 'စာသင်ခန်းများသည် သက်သောင့်သက်သာရှိပြီး ထိရောက်သော သင်ယူမှုကို အထောက်အကူပြုနိုင်သည့် သင်ယူမှုပတ်ဝန်းကျင် ဖြစ်ပါသည်။', '2026-08-06 06:40:00'),
(303, 32, 39, 'LE2', 'The classrooms are clean, safe, and well maintained.', 'စာသင်ခန်းများသည် သန့်ရှင်းသပ်ရပ်၍ လုံခြုံစိတ်ချရသည့်အပြင် ကောင်းမွန်စွာ ပြုပြင်ထိန်းသိမ်းထားရှိပါသည်။', '2026-08-06 06:40:00'),
(304, 32, 39, 'LE3', 'Classroom facilities (e.g., lighting, seating, ventilation, and audio-visual equipment) are adequate.', 'စာသင်ခန်းများတွင် အလင်းရောင်၊ ထိုင်ခုံ၊ လေဝင်လေထွက်နှင့် သင်ကြားသင်ယူရေးဆိုင်ရာ အထောက်အကူပြုပစ္စည်းများ လုံလောက်စွာ ရှိပါသည်။', '2026-08-06 06:40:00'),
(305, 32, 39, 'LE4', 'Learning resources (e.g., library and learning materials) are sufficient to support my studies.', 'စာကြည့်တိုက်တွင် ကျောင်းသား/သူများ လေ့လာဖတ်ရှုနိုင်ရန် နည်းပညာစာအုပ်များ၊ သုတရသစာအုပ်များ လုံလောက်စွာရှိပါသည်။', '2026-08-06 06:40:00'),
(306, 32, 39, 'LE5', 'The university provides reliable internet and Wi-Fi access for learning.', 'တက္ကသိုလ်မှ ပံ့ပိုးပေးထားသော Internet/Wi-Fi ဝန်ဆောင်မှုသည် သင်ယူလေ့လာရေး၊ သုတေသနလုပ်ငန်းများနှင့် ပညာရေးဆိုင်ရာ လှုပ်ရှားမှုများအတွက် ထိရောက်စွာ အထောက်အကူပြုပါသည်။', '2026-08-06 06:40:00'),
(307, 32, 39, 'LE6', 'The online learning platform(Learning Management System) is easy to access and use.', 'Online Learning Platform (Learning Management System) သည် အသုံးပြုရ လွယ်ကူအဆင်ပြေပြီး သင်ကြားသင်ယူရေးဆိုင်ရာ လုပ်ငန်းစဉ်များကို ထိရောက်စွာ အထောက်အကူပြုပါသည်။', '2026-08-06 06:40:00'),
(308, 32, 39, 'LE7', 'The learning environment encourages active participation and collaboration among students.', 'တက္ကသိုလ်၏ သင်ယူမှုပတ်ဝန်းကျင်သည် ကျောင်းသား/သူများအကြား တက်ကြွစွာ ပါဝင်ဆောင်ရွက်မှု၊ ပူးပေါင်းသင်ယူမှုနှင့် အပြန်အလှန် အသိပညာဖလှယ်မှုတို့ကို အားပေးမြှင့်တင်ပေးပါသည်။', '2026-08-06 06:40:00'),
(309, 32, 39, 'LE8', 'The university provides a supportive and inclusive learning atmosphere.', 'တက္ကသိုလ်သည် ကျောင်းသား/သူအားလုံးအတွက် တန်းတူညီမျှ အခွင့်အရေးရရှိစေပြီး အားပေးကူညီပံ့ပိုးပေးသော၊ အားလုံးပါဝင်နိုင်သည့် သင်ယူမှုပတ်ဝန်းကျင်ကို ဖန်တီးပေးပါသည်။', '2026-08-06 06:40:00'),
(310, 32, 39, 'LE9', 'The campus environment is conducive to learning and academic success.', 'တက္ကသိုလ်၏ ကျောင်းဝင်းပတ်ဝန်းကျင်သည် သင်ယူလေ့လာမှု၊ ပညာရေးဆိုင်ရာ ဖွံ့ဖြိုးတိုးတက်မှုနှင့် ပညာရေးအောင်မြင်မှုတို့ကို အထောက်အကူပြုနိုင်သော အရည်အသွေးမြင့် ပတ်ဝန်းကျင်တစ်ခု ဖြစ်ပါသည်။', '2026-08-06 06:40:00'),
(311, 32, 39, 'LE10', 'Overall, I am satisfied with the university\'s learning environment.', 'ယေဘုယျအားဖြင့် တက္ကသိုလ်၏ သင်ယူမှုပတ်ဝန်းကျင်၊ သင်ကြားသင်ယူရေးဆိုင်ရာ အထောက်အပံ့များနှင့် ပညာရေးဆိုင်ရာ အဆောက်အအုံများ၏ အရည်အသွေးအပေါ် ကျွန်ုပ် ကျေနပ်အားရမှုရှိပါသည်။', '2026-08-06 06:40:00'),
(331, 34, 41, 'TQ1', 'The lecturer is well prepared for each class.', 'ဆရာ/မသည် အတန်းတစ်ခုချင်းစီအတွက် သင်ကြားရမည့် သင်ခန်းစာများကို စနစ်တကျ ကြိုတင်ပြင်ဆင်၍ သင်ကြားပေးပါသည်။', '2026-08-15 18:27:46'),
(332, 34, 41, 'TQ2', 'The lecturer explains the course content clearly and understandably.', 'ဆရာ/မသည် သင်ခန်းစာအကြောင်းအရာများကို ရှင်းလင်းတိကျပြီး နားလည်လွယ်ကူစွာ ရှင်းပြသင်ကြားပေးပါသည်။', '2026-08-15 18:27:46'),
(333, 34, 41, 'TQ3', 'The lecturer demonstrates good knowledge of the subject.', 'ဆရာ/မသည် သင်ကြားသည့် ဘာသာရပ်နှင့်ပတ်သက်၍ ကျွမ်းကျင်မှုနှင့် လုံလောက်သော ဘာသာရပ်ဆိုင်ရာ အသိပညာကို ပိုင်ဆိုင်ထားပါသည်။', '2026-08-15 18:27:46'),
(334, 34, 41, 'TQ4', 'The lecturer uses effective teaching methods.', 'ဆရာ/မသည် သင်ကြားရာတွင် ကျောင်းသား/သူများ၏ သင်ယူမှုကို အထောက်အကူပြုနိုင်သော ထိရောက်သည့် သင်ကြားရေးနည်းလမ်းများကို အသုံးပြုပါသည်။', '2026-08-15 18:27:46'),
(335, 34, 41, 'TQ5', 'The lecturer encourages students to participate actively in class.', 'ဆရာ/မသည် ကျောင်းသား/သူများအား အတန်းတွင်း ဆွေးနွေးမှုများတွင် တက်ကြွစွာ ပါဝင်ဆောင်ရွက်နိုင်ရန် အားပေးမြှင့်တင်ပေးပါသည်။', '2026-08-15 18:27:46'),
(336, 34, 41, 'TQ6', 'The lecturer responds to students\' questions effectively.', 'ဆရာ/မသည် ကျောင်းသား/သူများ၏ မေးခွန်းများကို ရှင်းလင်းတိကျပြီး နားလည်လွယ်ကူစွာ ဖြေကြားရှင်းလင်းပေးပါသည်။', '2026-08-15 18:27:46'),
(337, 34, 41, 'TQ7', 'The lecturer provides students with sufficient opportunities for meaningful interaction and discussion.', 'ဆရာ/မသည် ကျောင်းသား/သူများနှင့် အပြန်အလှန် ဆက်သွယ်ဆွေးနွေးမှုကို ထိရောက်စွာ ဆောင်ရွက်ပေးပြီး သင်ယူမှုအပေါ် လိုအပ်သော လမ်းညွှန်မှုနှင့် အကြံပြုချက်များကို ပံ့ပိုးပေးပါသည်။', '2026-08-15 18:27:46'),
(338, 34, 41, 'TQ8', 'The lecturer treats students with respect and fairness.', 'ဆရာ/မသည် ကျောင်းသား/သူများအား အပြန်အလှန်လေးစားမှု၊ တရားမျှတမှုနှင့် ပရော်ဖက်ရှင်နယ် ကျင့်ဝတ်တို့ဖြင့် ဆက်ဆံပါသည်။', '2026-08-15 18:27:46'),
(339, 34, 41, 'TQ9', 'The lecturer motivates me to learn and perform well.', 'ဆရာ/မ၏ သင်ကြားပို့ချမှုသည် ကျွန်ုပ်၏ သင်ယူလိုစိတ်နှင့် ပညာရပ်ဆိုင်ရာ စိတ်ဝင်စားမှုကို မြှင့်တင်ပေးပါသည်။', '2026-08-15 18:27:46'),
(340, 34, 41, 'TQ10', 'The course objectives are clearly stated.', 'ဆရာ/မသည် သင်ကြားသောဘာသာရပ်၏ ရည်မှန်းချက်များကို နားလည်အောင် ရှင်းပြပါသည်။', '2026-08-15 18:27:46'),
(341, 34, 41, 'TQ11', 'The course content is relevant to my academic and professional needs.', 'ဆရာ/မသည် ဤဘာသာရပ်ကို ကျွန်ုပ်၏ ပညာရေးဆိုင်ရာ ရည်မှန်းချက်များနှင့် အနာဂတ်အသက်မွေးဝမ်းကျောင်းဆိုင်ရာ လိုအပ်ချက်များနှင့် ကိုက်ညီအောင် သင်ကြားပေးပါသည်။', '2026-08-15 18:27:46'),
(342, 34, 41, 'TQ12', 'The course content is well organized and logically structured.', 'ဆရာ/မသည် သင်ခန်းစာအကြောင်းအရာများကို စနစ်တကျ ဖွဲ့စည်းတင်ပြထားပြီး သင်ယူရန် သင့်လျော်စွာ စီစဉ်ထားပါသည်။', '2026-08-15 18:27:46'),
(343, 34, 41, 'TQ13', 'The course content is up to date and reflects current knowledge in the field.', 'ဆရာ/မသည် ဤဘာသာရပ်ကို ခေတ်နှင့်အညီ မွမ်းမံထားပြီး လက်ရှိ လုပ်ငန်းခွင် လိုအပ်ချက်များနှင့် ကိုက်ညီအောင်သင်ကြားပေးပါသည်။', '2026-08-15 18:27:46'),
(344, 34, 41, 'TQ14', 'The course materials (e.g., textbooks, handouts, slides) support my learning effectively.', 'ဆရာ/မသည် သင်ခန်းစာအကြောင်းအရာများကို ပိုမိုနားလည်စေရန် သင်ထောက်ကူပစ္စည်းများအသုံးပြု၍ ထိရောက်စွာသင်ကြားပေးပါသည်။', '2026-08-15 18:27:46'),
(345, 34, 41, 'TQ15', 'The course content helps me develop knowledge and practical skills.', 'ဆရာ/မ၏ သင်ကြားမှုများသည် ကျွန်ုပ်တို့၏ လက်တွေ့အသုံးချနိုင်သော ကျွမ်းကျင်မှုများကို ဖွံ့ဖြိုးတိုးတက်စေပါသည်။', '2026-08-15 18:27:46'),
(346, 34, 41, 'TQ16', 'The workload of the course is appropriate for the assigned credit hours.', 'ဆရာ/မသည် ဤဘာသာရပ်အတွက် လက်တွေ့အသုံးဝင်မှုကို အထောက်အကူပြုသော assignmentများ၊ projectများ၊ tutorialများ၊quiz များကို အသုံးပြု၍ learning assessment များပြုလုပ်ပါသည်။', '2026-08-15 18:27:46'),
(347, 34, 41, 'TQ17', 'The assessments (assignments, quizzes, exams) are aligned with the course content.', 'ဆရာ/မ ပြုလုပ်သော assessment များသည် သင်ခန်းစာအကြောင်းအရာများနှင့် သင်ယူရမည့် ရည်မှန်းချက်ပန်းတိုင်သို့ ရောက်အောင် အကဲဖြတ်နိုင်ပါသည်။', '2026-08-15 18:27:46'),
(348, 34, 41, 'TQ18', 'The course content encourages critical thinking and problem-solving skills.', 'သင်ခန်းစာအကြောင်းအရာများသည် ကျောင်းသား/သူများ၏ ဝေဖန်စဉ်းစားနိုင်စွမ်း၊ ဆန်းစစ်လေ့လာနိုင်စွမ်းနှင့် ပြဿနာဖြေရှင်းနိုင်စွမ်းတို့ကို မြှင့်တင်ပေးပါသည်။', '2026-08-15 18:27:46'),
(349, 34, 41, 'TQ19', 'Overall, I am satisfied with the quality of teaching provided by the lecturer.', 'ယေဘုယျအားဖြင့် ဤဘာသာရပ်နှင့်ပတ်သက်၍ ဆရာ/မ၏ သင်ကြားမှုနည်းစနစ်ကို နှစ်သက်ပါသည်။', '2026-08-15 18:27:46'),
(350, 35, 42, 'SA1', 'Career guidance and employment services provided by the university are beneficial to my future career development.', 'တက္ကသိုလ်မှ ပံ့ပိုးပေးသော အသက်မွေးဝမ်းကျောင်းလမ်းညွှန်မှုနှင့် အလုပ်အကိုင်အခွင့်အလမ်းဆိုင်ရာ ဝန်ဆောင်မှုများသည် ကျွန်ုပ်၏ အနာဂတ်အသက်မွေးဝမ်းကျောင်း ဖွံ့ဖြိုးတိုးတက်ရေးအတွက် အထောက်အကူပြုပါသည်။', '2026-08-15 18:28:38'),
(351, 35, 42, 'SA2', 'University announcements and important information are communicated to students in a timely manner.', 'တက္ကသိုလ်မှ ထုတ်ပြန်သော ကြေညာချက်များနှင့် အရေးကြီးသော သတင်းအချက်အလက်များကို အချိန်နှင့်တစ်ပြေးညီ သိရှိပါသည်။', '2026-08-15 18:28:38'),
(352, 35, 42, 'SA3', 'Information about scholarships and financial assistance is readily available and sufficient.', 'ပညာသင်ဆု (Scholarship) နှင့် ငွေကြေးအထောက်အပံ့ဆိုင်ရာ အချက်အလက်များကို လုံလောက်စွာ ရရှိပါသည်။', '2026-08-15 18:28:38'),
(353, 35, 42, 'SA4', 'The Student Affairs Office effectively supports and assists students with their needs.', 'ကျောင်းသားရေးရာဌာန (Student Affairs) သည် ကျောင်းသား/သူများ၏ လိုအပ်ချက်များနှင့် အခက်အခဲများကို ထိရောက်စွာ ဖြေရှင်းပေးပြီး လိုအပ်သော ပံ့ပိုးကူညီမှုများကို ပေးအပ်ပါသည်။', '2026-08-15 18:28:38'),
(354, 35, 42, 'SA5', 'Seminars, ICT Project Shows, and training programs organized by the university contribute to my personal and professional development.', 'တက္ကသိုလ်မှ ကျင်းပသော ဟောပြောပွဲများ၊ ICT Project Show များနှင့် သင်တန်းများသည် ကျွန်ုပ်၏ ကိုယ်ရည်ကိုယ်သွေး ဖွံ့ဖြိုးတိုးတက်ရေးနှင့် အသက်မွေးဝမ်းကျောင်းဆိုင်ရာ ကျွမ်းကျင်မှုများ တိုးတက်ရေးအတွက် အထောက်အကူပြုပါသည်။', '2026-08-15 18:28:38'),
(355, 35, 42, 'SA6', 'The university organizes sports competitions (e.g., football, volleyball, badminton, and other sports) in a well-planned manner and encourages student participation.', 'တက္ကသိုလ်သည် ဘောလုံး၊ ဘော်လီဘော၊ ကြက်တောင်နှင့် အခြားအားကစားပြိုင်ပွဲများတွင် ကျောင်းသား/သူများ ပါဝင်နိုင်ရန် စနစ်တကျ စီစဉ်ပံ့ပိုးပေးပါသည်။', '2026-08-15 18:28:38'),
(356, 35, 42, 'SA7', 'The university organizes traditional Myanmar cultural events, such as the Thanaka Application Competition and Htamane Festival, in an engaging and meaningful way.', 'တက္ကသိုလ်သည် သနပ်ခါးလိမ်းပြိုင်ပွဲ၊ ထမနဲထိုးပွဲကဲ့သို့သော မြန်မာ့ရိုးရာယဉ်ကျေးမှုဆိုင်ရာ လှုပ်ရှားမှုများကို စိတ်ဝင်စားဖွယ်ကောင်းစွာ စီစဉ်ကျင်းပပေးပါသည်။', '2026-08-15 18:28:38'),
(357, 35, 42, 'SA8', 'Sports and cultural activities organized by the university promote teamwork, collaboration, and friendship among students.', 'တက္ကသိုလ်မှ စီစဉ်ကျင်းပသော အားကစားပွဲနှင့် ယဉ်ကျေးမှုပွဲများသည် ကျောင်းသား/သူများအကြား အပြန်အလှန်ပူးပေါင်းဆောင်ရွက်မှု၊ ချစ်ကြည်ရင်းနှီးမှုနှင့် အသင်းအဖွဲ့စိတ်ဓာတ်ကို တိုးမြှင့်ပေးပါသည်။', '2026-08-15 18:28:38'),
(358, 35, 42, 'SA9', 'The university listens to students\' suggestions and feedback and takes appropriate action when necessary.', 'တက္ကသိုလ်သည် ကျောင်းသား/သူများ၏ အကြံပြုချက်များနှင့် အမြင်များကို အလေးထားနားထောင်ပြီး လိုအပ်သည့်အတိုင်း တာဝန်ယူ၍ ဆောင်ရွက်ပေးပါသည်။', '2026-08-15 18:28:38'),
(359, 35, 42, 'SA10', 'Overall, I am satisfied with the student activities and events organized by the university.', 'ယေဘုယျအားဖြင့် တက္ကသိုလ်မှ စီစဉ်ကျင်းပသော ကျောင်းသားလှုပ်ရှားမှုများ၊ အားကစားနှင့် ယဉ်ကျေးမှုဆိုင်ရာ ပွဲလမ်းသဘင်များအပေါ် ကျွန်ုပ် ကျေနပ်အားရမှုရှိပါသည်။', '2026-08-15 18:28:38'),
(360, 36, 43, 'LE1', 'The classrooms provide a comfortable learning environment.', 'စာသင်ခန်းများသည် သက်သောင့်သက်သာရှိပြီး ထိရောက်သော သင်ယူမှုကို အထောက်အကူပြုနိုင်သည့် သင်ယူမှုပတ်ဝန်းကျင် ဖြစ်ပါသည်။', '2026-08-15 18:29:00'),
(361, 36, 43, 'LE2', 'The classrooms are clean, safe, and well maintained.', 'စာသင်ခန်းများသည် သန့်ရှင်းသပ်ရပ်၍ လုံခြုံစိတ်ချရသည့်အပြင် ကောင်းမွန်စွာ ပြုပြင်ထိန်းသိမ်းထားရှိပါသည်။', '2026-08-15 18:29:00'),
(362, 36, 43, 'LE3', 'Classroom facilities (e.g., lighting, seating, ventilation, and audio-visual equipment) are adequate.', 'စာသင်ခန်းများတွင် အလင်းရောင်၊ ထိုင်ခုံ၊ လေဝင်လေထွက်နှင့် သင်ကြားသင်ယူရေးဆိုင်ရာ အထောက်အကူပြုပစ္စည်းများ လုံလောက်စွာ ရှိပါသည်။', '2026-08-15 18:29:00'),
(363, 36, 43, 'LE4', 'Learning resources (e.g., library and learning materials) are sufficient to support my studies.', 'စာကြည့်တိုက်တွင် ကျောင်းသား/သူများ လေ့လာဖတ်ရှုနိုင်ရန် နည်းပညာစာအုပ်များ၊ သုတရသစာအုပ်များ လုံလောက်စွာရှိပါသည်။', '2026-08-15 18:29:00'),
(364, 36, 43, 'LE5', 'The university provides reliable internet and Wi-Fi access for learning.', 'တက္ကသိုလ်မှ ပံ့ပိုးပေးထားသော Internet/Wi-Fi ဝန်ဆောင်မှုသည် သင်ယူလေ့လာရေး၊ သုတေသနလုပ်ငန်းများနှင့် ပညာရေးဆိုင်ရာ လှုပ်ရှားမှုများအတွက် ထိရောက်စွာ အထောက်အကူပြုပါသည်။', '2026-08-15 18:29:00'),
(365, 36, 43, 'LE6', 'The online learning platform(Learning Management System) is easy to access and use.', 'Online Learning Platform (Learning Management System) သည် အသုံးပြုရ လွယ်ကူအဆင်ပြေပြီး သင်ကြားသင်ယူရေးဆိုင်ရာ လုပ်ငန်းစဉ်များကို ထိရောက်စွာ အထောက်အကူပြုပါသည်။', '2026-08-15 18:29:00'),
(366, 36, 43, 'LE7', 'The learning environment encourages active participation and collaboration among students.', 'တက္ကသိုလ်၏ သင်ယူမှုပတ်ဝန်းကျင်သည် ကျောင်းသား/သူများအကြား တက်ကြွစွာ ပါဝင်ဆောင်ရွက်မှု၊ ပူးပေါင်းသင်ယူမှုနှင့် အပြန်အလှန် အသိပညာဖလှယ်မှုတို့ကို အားပေးမြှင့်တင်ပေးပါသည်။', '2026-08-15 18:29:00'),
(367, 36, 43, 'LE8', 'The university provides a supportive and inclusive learning atmosphere.', 'တက္ကသိုလ်သည် ကျောင်းသား/သူအားလုံးအတွက် တန်းတူညီမျှ အခွင့်အရေးရရှိစေပြီး အားပေးကူညီပံ့ပိုးပေးသော၊ အားလုံးပါဝင်နိုင်သည့် သင်ယူမှုပတ်ဝန်းကျင်ကို ဖန်တီးပေးပါသည်။', '2026-08-15 18:29:00'),
(368, 36, 43, 'LE9', 'The campus environment is conducive to learning and academic success.', 'တက္ကသိုလ်၏ ကျောင်းဝင်းပတ်ဝန်းကျင်သည် သင်ယူလေ့လာမှု၊ ပညာရေးဆိုင်ရာ ဖွံ့ဖြိုးတိုးတက်မှုနှင့် ပညာရေးအောင်မြင်မှုတို့ကို အထောက်အကူပြုနိုင်သော အရည်အသွေးမြင့် ပတ်ဝန်းကျင်တစ်ခု ဖြစ်ပါသည်။', '2026-08-15 18:29:00'),
(369, 36, 43, 'LE10', 'Overall, I am satisfied with the university\'s learning environment.', 'ယေဘုယျအားဖြင့် တက္ကသိုလ်၏ သင်ယူမှုပတ်ဝန်းကျင်၊ သင်ကြားသင်ယူရေးဆိုင်ရာ အထောက်အပံ့များနှင့် ပညာရေးဆိုင်ရာ အဆောက်အအုံများ၏ အရည်အသွေးအပေါ် ကျွန်ုပ် ကျေနပ်အားရမှုရှိပါသည်။', '2026-08-15 18:29:00');

